  1330	func semanticStaleReport(ctx context.Context, opts Options, target string) (staleReport, error) {
  1331		repoDir, local, err := resolveLocalTargetRepoDir(ctx, opts.Runner, target)
  1332		if err != nil {
  1333			return staleReport{}, err
  1334		}
  1335		if !local {
  1336			return staleReport{}, fmt.Errorf("stale requires a local repository path: %s", target)
  1337		}
  1338		storage, err := repoStoragePaths(ctx, opts.Runner, opts.Env, repoDir)
  1339		if err != nil {
  1340			return staleReport{}, err
  1341		}
  1342		manifest, err := loadBrainManifest(storage.BrainDir)
  1343		if err != nil {
  1344			return staleReport{}, err
  1345		}
  1346		axes := map[string]staleAxis{}
  1347		if manifest.Sources == nil || manifest.Sources.Semantic == nil {
  1348			axes["semantic"] = staleAxis{State: "missing", Detail: "no semantic source in manifest"}
  1349			return staleReport{Severity: "unsafe", Axes: axes}, nil
  1350		}
  1351		source := manifest.Sources.Semantic
  1352		if source.SnapshotPath == "" {
  1353			axes["snapshot"] = staleAxis{State: "unsafe", Detail: "semantic snapshot_path is missing"}
  1354		} else if _, err := validateSemanticSnapshotPath(source.SnapshotPath); err != nil {
  1355			axes["snapshot"] = staleAxis{State: "unsafe", Detail: err.Error()}
  1356		} else if err := rejectSymlinkPathComponents(storage.BrainDir, filepath.FromSlash(source.SnapshotPath)); err != nil {
  1357			axes["snapshot"] = staleAxis{State: "unsafe", Detail: err.Error()}
  1358		} else {
  1359			snapshotPath := filepath.Join(storage.BrainDir, filepath.FromSlash(source.SnapshotPath))
  1360			snapshotHeader, snapshotCounts, snapshotErr := readSemanticSnapshotSummary(snapshotPath, storage.Key)
  1361			if snapshotErr != nil {
  1362				axes["snapshot"] = staleAxis{State: "unsafe", Detail: snapshotErr.Error()}
  1363			} else if err := validateSemanticSourceMatchesSnapshot(source, snapshotHeader, snapshotCounts); err != nil {
  1364				axes["snapshot"] = staleAxis{State: "unsafe", Detail: err.Error()}
  1365			} else {
  1366				axes["snapshot"] = staleAxis{State: "ok", Detail: source.SnapshotPath}
  1367			}
  1368		}
  1369		if source.StorePath != "" {
  1370			if source.GenerationPath == "" {
  1371				axes["store"] = staleAxis{State: "unsafe", Detail: "semantic generation_path is missing"}
  1372			} else if generationPath, err := validateSemanticGenerationPath(source.GenerationPath); err != nil {
  1373				axes["store"] = staleAxis{State: "unsafe", Detail: err.Error()}
  1374			} else if storePath, err := validateSemanticGenerationFilePath(source.StorePath, generationPath, semanticSQLiteName); err != nil {
  1375				axes["store"] = staleAxis{State: "unsafe", Detail: err.Error()}
  1376			} else if err := rejectSymlinkPathComponents(storage.BrainDir, storePath); err != nil {
  1377				axes["store"] = staleAxis{State: "unsafe", Detail: err.Error()}
  1378			} else if err := validateSemanticSQLiteStore(filepath.Join(storage.BrainDir, storePath), source.Symbols, source.Relations); err != nil {
  1379				axes["store"] = staleAxis{State: "unsafe", Detail: err.Error()}
  1380			} else {
  1381				axes["store"] = staleAxis{State: "ok", Detail: source.StorePath}
  1382			}
  1383		}
  1384		head, _ := gitScalar(ctx, opts.Runner, repoDir, "rev-parse", "HEAD")
  1385		branch, _ := gitScalar(ctx, opts.Runner, repoDir, "branch", "--show-current")
  1386		dirty, dirtyErr := worktreeDirty(ctx, opts.Runner, repoDir)
  1387		currentWorktreeHash := ""
  1388		var currentWorktreeHashErr error
  1389		if dirty && source.WorktreeHash != "" {
  1390			currentWorktreeHash, currentWorktreeHashErr = worktreeFingerprint(ctx, opts.Runner, repoDir)
  1391		}
  1392		if source.Commit == head {
  1393			axes["head"] = staleAxis{State: "ok", Current: head, Indexed: source.Commit}
  1394		} else {
  1395			axes["head"] = staleAxis{State: "stale", Current: head, Indexed: source.Commit}
  1396		}
  1397		if source.Branch == "" || source.Branch == branch {
  1398			axes["branch_tip"] = staleAxis{State: "ok", Current: branch, Indexed: source.Branch}
  1399		} else {
  1400			axes["branch_tip"] = staleAxis{State: "stale", Current: branch, Indexed: source.Branch}
  1401		}
  1402		switch {
  1403		case dirtyErr != nil:
  1404			axes["worktree"] = staleAxis{State: "unsafe", Detail: "worktree status unavailable: " + dirtyErr.Error()}
  1405		case dirty && source.WorktreeMode != "worktree":
  1406			axes["worktree"] = staleAxis{State: "dirty-unindexed", Detail: "semantic index is based on committed HEAD"}
  1407		case currentWorktreeHashErr != nil:
  1408			axes["worktree"] = staleAxis{State: "unsafe", Detail: "worktree fingerprint unavailable: " + currentWorktreeHashErr.Error()}
  1409		case dirty && source.WorktreeHash != "" && source.WorktreeHash != currentWorktreeHash:
  1410			axes["worktree"] = staleAxis{State: "dirty-stale", Detail: "dirty worktree changed since semantic indexing"}
  1411		case dirty:
  1412			axes["worktree"] = staleAxis{State: "dirty-indexed"}
  1413		case source.WorktreeMode == "worktree":
  1414			axes["worktree"] = staleAxis{State: "worktree-overlay-stale", Detail: "active semantic index was built from dirty content but worktree is now clean"}
  1415		default:
  1416			axes["worktree"] = staleAxis{State: "clean"}
  1417		}
  1418		if source.Provider == "skipped" || semanticWarningsContainCode(source.Warnings, "provider_skipped") {
  1419			axes["provider"] = staleAxis{State: "degraded", Detail: "semantic provider was skipped"}
  1420		} else if err := validateSemanticSchema(source.SchemaVersion); err != nil {
  1421			axes["provider"] = staleAxis{State: "unsafe", Detail: err.Error()}
  1422		} else if !source.NoEgressVerified {
  1423			axes["provider"] = staleAxis{State: "degraded", Detail: "provider no-egress status was not verified"}
  1424		} else {
  1425			axes["provider"] = staleAxis{State: "ok", Detail: source.Provider + " " + source.ProviderVersion}
  1426		}
  1427		if source.Provider == "skipped" || semanticWarningsContainCode(source.Warnings, "provider_skipped") {
  1428			axes["semantic_completeness"] = staleAxis{State: "unsafe", Detail: "semantic facts unavailable"}
  1429		} else if len(source.PartialFailures) > 0 {
  1430			axes["semantic_completeness"] = staleAxis{State: "degraded", Detail: strconv.Itoa(len(source.PartialFailures)) + " partial failures"}
  1431		} else {
  1432			axes["semantic_completeness"] = staleAxis{State: "ok"}
  1433		}
  1434		severity := aggregateStaleSeverity(axes)
  1435		return staleReport{Severity: severity, Axes: axes, Warnings: source.Warnings}, nil
  1436	}
