  1668	func runSemanticQuery(ctx context.Context, cmd *cobra.Command, opts Options, queryOpts semanticQueryOptions, query string) error {
  1669		if queryOpts.limit <= 0 {
  1670			return errors.New("--limit must be greater than zero")
  1671		}
  1672		if queryOpts.offset < 0 {
  1673			return errors.New("--offset must be zero or greater")
  1674		}
  1675		repoDir, err := exportRepoDir(opts.Env)
  1676		if err != nil {
  1677			return err
  1678		}
  1679		storage, err := repoStoragePaths(ctx, opts.Runner, opts.Env, repoDir)
  1680		if err != nil {
  1681			return err
  1682		}
  1683		if err := ensureSemanticAuditPathSafe(storage.BrainDir); err != nil {
  1684			return err
  1685		}
  1686		unlock, err := acquireSemanticIndexLock(storage.BrainDir)
  1687		if err != nil {
  1688			return err
  1689		}
  1690		defer unlock()
  1691		manifest, err := loadBrainManifest(storage.BrainDir)
  1692		if err != nil {
  1693			return err
  1694		}
  1695		freshness, err := semanticStaleReport(ctx, opts, repoDir)
  1696		if err != nil {
  1697			return err
  1698		}
  1699		if manifest.Sources == nil || manifest.Sources.Semantic == nil {
  1700			return errors.New("semantic index missing; run `entire brain index`")
  1701		}
  1702		snapshotPath, err := validateSemanticSnapshotPath(manifest.Sources.Semantic.SnapshotPath)
  1703		if err != nil {
  1704			return err
  1705		}
  1706		if err := rejectSymlinkPathComponents(storage.BrainDir, snapshotPath); err != nil {
  1707			return err
  1708		}
  1709		var results []semanticRecord
  1710		if manifest.Sources.Semantic.StorePath != "" {
  1711			storePath, err := validateSemanticDeclaredStore(storage.BrainDir, manifest.Sources.Semantic)
  1712			if err != nil {
  1713				return err
  1714			}
  1715			results, err = findSemanticSymbolsInSQLite(storePath, query, queryOpts.limit, queryOpts.offset)
  1716			if err != nil {
  1717				return err
  1718			}
  1719		} else {
  1720			results, err = findSemanticSymbols(filepath.Join(storage.BrainDir, snapshotPath), query, queryOpts.limit, queryOpts.offset)
  1721			if err != nil {
  1722				return err
  1723			}
  1724		}
  1725		if queryOpts.json {
  1726			data, err := json.MarshalIndent(struct {
  1727				Freshness  staleReport      `json:"freshness"`
  1728				Pagination semanticPage     `json:"pagination"`
  1729				Results    []semanticRecord `json:"results"`
  1730			}{Freshness: freshness, Pagination: semanticPage{Limit: queryOpts.limit, Offset: queryOpts.offset, Count: len(results)}, Results: results}, "", "  ")
  1731			if err != nil {
  1732				return err
  1733			}
  1734			fmt.Fprintln(cmd.OutOrStdout(), string(data))
  1735			return nil
  1736		}
  1737		if freshness.Severity != "ok" {
  1738			fmt.Fprintf(cmd.OutOrStdout(), "semantic freshness: %s\n", freshness.Severity)
  1739		}
  1740		for _, result := range results {
  1741			fmt.Fprintf(cmd.OutOrStdout(), "%s %s %s:%d-%d\n", result.Kind, displaySymbolName(result), result.FilePath, result.StartLine, result.EndLine)
  1742		}
  1743		return nil
  1744	}
